using GestionMagasin.Application;
using GestionMagasin.Domain;
using GestionMagasin.Infrastructure;

namespace GestionMagasin.WinForms;

public sealed class DashboardPanel : UserControl
{
    readonly Utilisateur actor;readonly ReportingService reporting;readonly Action<string>? openList;readonly FlowLayoutPanel cards=new(){Dock=DockStyle.Fill,Padding=new Padding(20),AutoScroll=true};public DashboardPanel(Utilisateur actor,ReportingService reporting,Action<string>? openList=null){this.actor=actor;this.reporting=reporting;this.openList=openList;Controls.Add(cards);Load+=async(_,_)=>await LoadAsync();}
    async Task LoadAsync(){cards.Controls.Clear();var data=await reporting.DashboardAsync(actor,DateTime.Today,TimeZoneInfo.Local.Id);cards.Controls.Add(Ui.Title($"Tableau de bord - {data.DateMetier:dd/MM/yyyy}"));AddCard("Ventes validées",$"{data.VentesFcfa:N0} FCFA",Color.FromArgb(38,110,170));AddCard("Nombre de ventes",data.NombreVentes.ToString(),Color.FromArgb(38,110,170));AddCard("Unités vendues",data.UnitesVendues.ToString(),Color.FromArgb(38,110,170));AddCard("Références en rupture",data.ReferencesEnRupture.ToString(),Color.Firebrick);AddCard("Références en stock faible",data.ReferencesStockFaible.ToString(),Color.DarkOrange);}
    void AddCard(string title,string value,Color color){var b=new Button{Text=$"{title}\n{value}",Width=250,Height=110,BackColor=color,ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Font=new Font("Segoe UI",12,FontStyle.Bold),Margin=new Padding(8)};b.Click+=(_,_)=>openList?.Invoke(title);cards.Controls.Add(b);}
}

public sealed class ReportsPanel : UserControl
{
    readonly Utilisateur actor;readonly ReportingService reporting;readonly ParametresService settings;readonly VenteService sales;readonly DataGridView grid=Ui.Grid();readonly DateTimePicker from=new(){Format=DateTimePickerFormat.Short,Value=DateTime.Today};readonly DateTimePicker to=new(){Format=DateTimePickerFormat.Short,Value=DateTime.Today};readonly ComboBox exportType=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=140};ParametresMagasin? config;
    public ReportsPanel(Utilisateur actor,ReportingService reporting,ParametresService settings,VenteService sales){this.actor=actor;this.reporting=reporting;this.settings=settings;this.sales=sales;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=74};top.Controls.Add(Ui.Title("Rapports"));top.Controls.Add(from);top.Controls.Add(to);var run=Ui.Button("Générer");run.Click+=async(_,_)=>await LoadAsync();top.Controls.Add(run);exportType.Items.AddRange(new object[]{"Ventes","Stock","Mouvements"});exportType.SelectedIndex=0;top.Controls.Add(exportType);var export=Ui.Button("Exporter CSV");export.Click+=async(_,_)=>await ExportAsync();top.Controls.Add(export);Controls.Add(grid);Controls.Add(top);Load+=async(_,_)=>{config=await settings.ObtenirAsync(actor);await LoadAsync();};}
    async Task LoadAsync(){config??=await settings.ObtenirAsync(actor);var rows=await reporting.VentesParProduitAsync(actor,from.Value.Date,to.Value.Date.AddDays(1),config.FuseauHoraire);grid.DataSource=rows.Select(x=>new{x.Reference,x.Nom,x.UnitesVendues,x.MontantFcfa}).ToList();var summary=await reporting.SyntheseAsync(actor,from.Value.Date,to.Value.Date.AddDays(1),config.FuseauHoraire);Text=$"Rapports - {summary.NombreVentes} ventes, {summary.UnitesVendues} unités, {summary.MontantFcfa:N0} FCFA";}
    async Task ExportAsync(){using var dialog=new SaveFileDialog{Filter="CSV Excel (*.csv)|*.csv",FileName=$"rapport-{DateTime.Now:yyyyMMdd}.csv"};if(dialog.ShowDialog()!=DialogResult.OK)return;try{config??=await settings.ObtenirAsync(actor);if(exportType.SelectedItem?.ToString()=="Ventes"){var rows=await sales.RechercherAsync(actor,null,from.Value.Date,to.Value.Date.AddDays(1),null,null);await CsvExporter.ExportAsync(dialog.FileName,new[]{"Numéro","Date","Vendeur","Montant FCFA","Paiement","Statut"},rows.Select(x=>new object?[]{x.Numero,x.DateMetier,x.Vendeur,x.TotalFcfa,x.ModePaiement,x.Statut}));}else{var rows=await reporting.StockAsync(actor);if(exportType.SelectedItem?.ToString()=="Stock")await CsvExporter.ExportAsync(dialog.FileName,new[]{"Produit","Type","Quantité","Motif","Date"},rows.GroupBy(x=>x.Mouvement.ProduitId).Select(g=>new object?[]{g.Key,"Stock courant",g.Sum(x=>x.Mouvement.Quantite),"",DateTime.UtcNow}));else await CsvExporter.ExportAsync(dialog.FileName,new[]{"Produit","Type","Quantité","Motif","Date"},rows.Select(x=>new object?[]{x.Mouvement.ProduitId,x.Mouvement.Type,x.Mouvement.Quantite,x.Mouvement.Motif,x.Mouvement.DateTechniqueUtc}));}MessageBox.Show("Export CSV terminé.");}catch(Exception ex){MessageBox.Show(ex.Message,"Export",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}

public sealed class SettingsPanel : UserControl
{
    readonly Utilisateur actor;readonly ParametresService settings;readonly SauvegardeService backup;readonly TextBox name=new(),coordinates=new(),logo=new(),currency=new(),zone=new(),policy=new();
    public SettingsPanel(Utilisateur actor,ParametresService settings,SauvegardeService backup){this.actor=actor;this.settings=settings;this.backup=backup;var p=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2,Padding=new Padding(12)};p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,30));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,70));Add(p,"Nom commercial",name);Add(p,"Coordonnées",coordinates);Add(p,"Logo (facultatif)",logo);Add(p,"Devise",currency);Add(p,"Fuseau horaire",zone);Add(p,"Politique sauvegarde",policy);var save=Ui.Button("Enregistrer les paramètres");save.Click+=async(_,_)=>{try{await settings.EnregistrerAsync(actor,new ParametresMagasin(name.Text,coordinates.Text,string.IsNullOrWhiteSpace(logo.Text)?null:logo.Text,currency.Text,zone.Text,policy.Text));MessageBox.Show("Paramètres enregistrés.");}catch(Exception ex){MessageBox.Show(ex.Message);}};p.Controls.Add(save,0,6);p.SetColumnSpan(save,2);var backupButton=Ui.Button("Sauvegarder maintenant");backupButton.Click+=async(_,_)=>await BackupAsync();p.Controls.Add(backupButton,0,7);var restore=Ui.Button("Restaurer une sauvegarde");restore.Click+=async(_,_)=>await RestoreAsync();p.Controls.Add(restore,1,7);Controls.Add(p);Load+=async(_,_)=>await LoadAsync();}
    async Task LoadAsync(){var p=await settings.ObtenirAsync(actor);name.Text=p.NomCommercial;coordinates.Text=p.Coordonnees;logo.Text=p.LogoPath??"";currency.Text=p.Devise;zone.Text=p.FuseauHoraire;policy.Text=p.PolitiqueSauvegarde;}
    async Task BackupAsync(){using var d=new SaveFileDialog{Filter="Base SQLite (*.db)|*.db",FileName=$"gestion-magasin-{DateTime.Now:yyyyMMdd-HHmmss}.db"};if(d.ShowDialog()!=DialogResult.OK)return;try{var result=await backup.SauvegarderAsync(actor,d.FileName);MessageBox.Show($"Sauvegarde réussie : {result.DateUtc.ToLocalTime():g}");}catch(Exception ex){MessageBox.Show(ex.Message,"Sauvegarde",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
    async Task RestoreAsync(){using var d=new OpenFileDialog{Filter="Base SQLite (*.db)|*.db"};if(d.ShowDialog()!=DialogResult.OK)return;if(MessageBox.Show("La base active sera sauvegardée avant restauration. Continuer ?","Confirmation",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{await backup.RestaurerAsync(actor,d.FileName);MessageBox.Show("Restauration terminée. Redémarrez l'application.");FindForm()?.Close();}catch(Exception ex){MessageBox.Show(ex.Message,"Restauration",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    static void Add(TableLayoutPanel p,string label,TextBox box){var row=p.RowCount++;p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);box.Dock=DockStyle.Fill;p.Controls.Add(box,1,row);}
}
